create table public.setup_claim_types (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, name text not null, description text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.setup_incident_types (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, name text not null, description text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.setup_project_types (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, name text not null, description text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.dynamic_setup_entities (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, table_name text not null, title text not null, description text, schema jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.dynamic_setup_records (id uuid primary key default gen_random_uuid(), entity_id uuid not null references public.dynamic_setup_entities(id) on delete cascade, org_id uuid not null references public.organizations(id) on delete cascade, data jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.security_scan_results (id uuid primary key default gen_random_uuid(), environment text not null default 'production', scan_type text not null, status text not null, detail jsonb, scanned_at timestamptz not null default now());
create table public.enterprise_audit_log (id uuid primary key default gen_random_uuid(), org_id uuid references public.organizations(id) on delete cascade, actor_id uuid, action text not null, resource_type text, resource_id text, outcome text, detail jsonb, created_at timestamptz not null default now());
create table public.activity_logs (id bigint generated by default as identity primary key, org_id uuid references public.organizations(id) on delete cascade, actor_id uuid, action text, payload jsonb, prev_hash text, curr_hash text, created_at timestamptz not null default now());

grant select, insert, update, delete on public.setup_claim_types to authenticated;
grant select, insert, update, delete on public.setup_incident_types to authenticated;
grant select, insert, update, delete on public.setup_project_types to authenticated;
grant select, insert, update, delete on public.dynamic_setup_entities to authenticated;
grant select, insert, update, delete on public.dynamic_setup_records to authenticated;
grant select on public.security_scan_results to authenticated;
grant select, insert on public.enterprise_audit_log to authenticated;
grant select, insert on public.activity_logs to authenticated;
grant all on public.setup_claim_types to service_role;
grant all on public.setup_incident_types to service_role;
grant all on public.setup_project_types to service_role;
grant all on public.dynamic_setup_entities to service_role;
grant all on public.dynamic_setup_records to service_role;
grant all on public.security_scan_results to service_role;
grant all on public.enterprise_audit_log to service_role;
grant all on public.activity_logs to service_role;
grant usage, select on sequence public.activity_logs_id_seq to authenticated;

alter table public.setup_claim_types enable row level security;
alter table public.setup_incident_types enable row level security;
alter table public.setup_project_types enable row level security;
alter table public.dynamic_setup_entities enable row level security;
alter table public.dynamic_setup_records enable row level security;
alter table public.security_scan_results enable row level security;
alter table public.enterprise_audit_log enable row level security;
alter table public.activity_logs enable row level security;

create policy "Org-scoped access" on public.setup_claim_types for all to authenticated using (org_id in (select org_id from public.organization_members where user_id = auth.uid())) with check (org_id in (select org_id from public.organization_members where user_id = auth.uid()));
create policy "Org-scoped access" on public.setup_incident_types for all to authenticated using (org_id in (select org_id from public.organization_members where user_id = auth.uid())) with check (org_id in (select org_id from public.organization_members where user_id = auth.uid()));
create policy "Org-scoped access" on public.setup_project_types for all to authenticated using (org_id in (select org_id from public.organization_members where user_id = auth.uid())) with check (org_id in (select org_id from public.organization_members where user_id = auth.uid()));
create policy "Org-scoped access" on public.dynamic_setup_entities for all to authenticated using (org_id in (select org_id from public.organization_members where user_id = auth.uid())) with check (org_id in (select org_id from public.organization_members where user_id = auth.uid()));
create policy "Org-scoped access" on public.dynamic_setup_records for all to authenticated using (org_id in (select org_id from public.organization_members where user_id = auth.uid())) with check (org_id in (select org_id from public.organization_members where user_id = auth.uid()));
create policy "Signed-in users can read scan results" on public.security_scan_results for select to authenticated using (true);
create policy "Org members can read audit log" on public.enterprise_audit_log for select to authenticated using (org_id in (select org_id from public.organization_members where user_id = auth.uid()));
create policy "Signed-in users can append audit events" on public.enterprise_audit_log for insert to authenticated with check (true);
create policy "Org members can read activity logs" on public.activity_logs for select to authenticated using (org_id in (select org_id from public.organization_members where user_id = auth.uid()));
create policy "Signed-in users can append activity logs" on public.activity_logs for insert to authenticated with check (true);